INSERT INTO `srt_panel` VALUES (/*reading_id*/1000100, /*reading*/'苹果', /*read_type*/1, /*panel_id*/10001, /*detail_text*/'红色，酸酸甜甜的水果。', /*version*/1, /*head_symbol*/'ing', /*tail_symbol*/'o');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000102, /*reading*/'禁断的果实', /*read_type*/2, /*panel_id*/10001, /*detail_text*/'传说中智慧之树上结出的果实。也有一种说法认为，这种果实并不是苹果。', /*version*/1, /*head_symbol*/'in', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000200, /*reading*/'猩猩', /*read_type*/1, /*panel_id*/10002, /*detail_text*/'又强大又黑，浑身都是肌肉。这种生物最喜欢香蕉。', /*version*/1, /*head_symbol*/'a', /*tail_symbol*/'ing');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000201, /*reading*/'灵长类', /*read_type*/2, /*panel_id*/10002, /*detail_text*/'是动物的其中一种类别。', /*version*/1, /*head_symbol*/'ing', /*tail_symbol*/'ei');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000202, /*reading*/'吼吼', /*read_type*/2, /*panel_id*/10002, /*detail_text*/'模拟猩猩的勇猛吼叫的拟声词。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'ou');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000203, /*reading*/'长耳猴首领', /*read_type*/3, /*panel_id*/10002, /*detail_text*/'在“露娜之塔”坐镇的强大仙猴。虽然不是猩猩而是猴子，但算是近亲，所以勉强合格。', /*version*/1, /*head_symbol*/'ang', /*tail_symbol*/'ing');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000301, /*reading*/'小号', /*read_type*/1, /*panel_id*/10003, /*detail_text*/'铜管乐器的一种。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'a');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000302, /*reading*/'管乐器', /*read_type*/2, /*panel_id*/10003, /*detail_text*/'乐器的其中一个分类。另外，“萨克斯练习”之类的公主连结专用读法，实际上是不存在的。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000400, /*reading*/'菠萝', /*read_type*/1, /*panel_id*/10004, /*detail_text*/'生长在温暖的地方，外表呈黄色的酸酸甜甜的水果。', /*version*/1, /*head_symbol*/'o', /*tail_symbol*/'o');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000401, /*reading*/'凤梨', /*read_type*/2, /*panel_id*/10004, /*detail_text*/'“菠萝”的另一种叫法。', /*version*/1, /*head_symbol*/'eng', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000500, /*reading*/'红宝石', /*read_type*/1, /*panel_id*/10005, /*detail_text*/'被称为宝石中的女王，外表呈鲜艳红色的宝石。', /*version*/1, /*head_symbol*/'ong', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000501, /*reading*/'宝石', /*read_type*/1, /*panel_id*/10005, /*detail_text*/'被当成装饰物，美丽而又稀少的贵价矿物。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000504, /*reading*/'秋乃的胸针', /*read_type*/3, /*panel_id*/10005, /*detail_text*/'“紫藤庐家”的大小姐“秋乃”佩戴的胸针。', /*version*/1, /*head_symbol*/'iu', /*tail_symbol*/'en');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000600, /*reading*/'像啤酒的饮料', /*read_type*/1, /*panel_id*/10006, /*detail_text*/'很像“啤酒”的饮料。', /*version*/1, /*head_symbol*/'ang', /*tail_symbol*/'ao');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000601, /*reading*/'酒杯', /*read_type*/1, /*panel_id*/10006, /*detail_text*/'一边有把手的饮料容器。', /*version*/1, /*head_symbol*/'iu', /*tail_symbol*/'ei');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000602, /*reading*/'麦酒', /*read_type*/3, /*panel_id*/10006, /*detail_text*/'“由加莉”对“像啤酒的饮料”的称呼。不能多喝。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'ui');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000603, /*reading*/'无尽酒杯', /*read_type*/3, /*panel_id*/10006, /*detail_text*/'“由加莉”的专属装备。不管怎么喝，饮料都能源源不断地涌出来。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'ei');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000700, /*reading*/'弓箭', /*read_type*/1, /*panel_id*/10007, /*detail_text*/'由弓和箭组成的武器。', /*version*/1, /*head_symbol*/'ong', /*tail_symbol*/'an');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000701, /*reading*/'远程武器', /*read_type*/2, /*panel_id*/10007, /*detail_text*/'指能进行远距离攻击的武器。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000800, /*reading*/'音符', /*read_type*/1, /*panel_id*/10008, /*detail_text*/'在音乐中用来记录声音的符号。', /*version*/1, /*head_symbol*/'in', /*tail_symbol*/'u');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000801, /*reading*/'旋律', /*read_type*/1, /*panel_id*/10008, /*detail_text*/'在音乐中由声音组成的序列。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'ü');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000803, /*reading*/'歌曲', /*read_type*/2, /*panel_id*/10008, /*detail_text*/'伴有歌声的音乐。', /*version*/1, /*head_symbol*/'e', /*tail_symbol*/'ü');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000900, /*reading*/'颜料', /*read_type*/1, /*panel_id*/10009, /*detail_text*/'为图画添上色彩的材料。', /*version*/1, /*head_symbol*/'ui', /*tail_symbol*/'ao');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1000902, /*reading*/'蓝色', /*read_type*/2, /*panel_id*/10009, /*detail_text*/'蓝色。或者形容忧郁的样子。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'e');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001000, /*reading*/'剑', /*read_type*/1, /*panel_id*/10010, /*detail_text*/'利用锋刃进行攻击的武器的统称。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'an');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001002, /*reading*/'双刃剑', /*read_type*/2, /*panel_id*/10010, /*detail_text*/'两边都有锋刃的剑。', /*version*/1, /*head_symbol*/'ang', /*tail_symbol*/'an');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001003, /*reading*/'利器', /*read_type*/2, /*panel_id*/10010, /*detail_text*/'指开锋的工具或武器。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001004, /*reading*/'公主之剑', /*read_type*/3, /*panel_id*/10010, /*detail_text*/'“佩可莉姆”的专属装备。给予佩可莉姆更强大力量的“皇家装备”的真正姿态。', /*version*/1, /*head_symbol*/'ong', /*tail_symbol*/'an');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001100, /*reading*/'眼镜', /*read_type*/1, /*panel_id*/10011, /*detail_text*/'佩戴在眼睛前，用于矫正视力的道具。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'ing');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001101, /*reading*/'镜片', /*read_type*/2, /*panel_id*/10011, /*detail_text*/'可用在眼镜和各种东西上，能折射光线的透明物体。', /*version*/1, /*head_symbol*/'ing', /*tail_symbol*/'an');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001102, /*reading*/'瓶底眼镜', /*read_type*/2, /*panel_id*/10011, /*detail_text*/'镜片像瓶底一样厚重的眼镜。', /*version*/1, /*head_symbol*/'üe', /*tail_symbol*/'a');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001103, /*reading*/'圈圈眼镜', /*read_type*/2, /*panel_id*/10011, /*detail_text*/'可以用来变装，摘下眼镜后有可能会是个美人。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'ü');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001104, /*reading*/'花凛的眼镜', /*read_type*/3, /*panel_id*/10011, /*detail_text*/'公会之家的管理人“花凛”佩戴的眼镜。', /*version*/1, /*head_symbol*/'a', /*tail_symbol*/'ing');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001200, /*reading*/'放大镜', /*read_type*/1, /*panel_id*/10012, /*detail_text*/'将小东西放大的道具。', /*version*/1, /*head_symbol*/'ang', /*tail_symbol*/'ing');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001201, /*reading*/'镜片', /*read_type*/1, /*panel_id*/10012, /*detail_text*/'可用在放大镜和各种东西上，能折射光线的透明物体。', /*version*/1, /*head_symbol*/'ing', /*tail_symbol*/'an');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001203, /*reading*/'变焦', /*read_type*/2, /*panel_id*/10012, /*detail_text*/'利用镜片将物品放大缩小来查看的操作。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'ao');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001205, /*reading*/'侦探放大镜', /*read_type*/3, /*panel_id*/10012, /*detail_text*/'“香澄”的专属装备。她跟这放大镜共同经历了数个案件。', /*version*/1, /*head_symbol*/'en', /*tail_symbol*/'ing');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001300, /*reading*/'肉', /*read_type*/1, /*panel_id*/10013, /*detail_text*/'烤熟后会变得鲜嫩多汁的美味食材。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'ou');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001301, /*reading*/'烹饪', /*read_type*/2, /*panel_id*/10013, /*detail_text*/'将食材进行加工、调味以便\n食用。', /*version*/1, /*head_symbol*/'eng', /*tail_symbol*/'en');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001303, /*reading*/'排骨', /*read_type*/2, /*panel_id*/10013, /*detail_text*/'带有骨头的肉。以及以此材料烹饪出的菜肴。只要连肉带骨，看起来就显得美味。', /*version*/1, /*head_symbol*/'ang', /*tail_symbol*/'u');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001304, /*reading*/'龙肉', /*read_type*/2, /*panel_id*/10013, /*detail_text*/'这么美味的排骨，说不定是传说中出自厄尔庇斯岛的“龙族”的肉呢。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'ou');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001305, /*reading*/'龙肉', /*read_type*/3, /*panel_id*/10013, /*detail_text*/'这么美味的排骨，说不定是传说中出自厄尔庇斯岛的“龙族”的肉呢。', /*version*/1, /*head_symbol*/'ong', /*tail_symbol*/'ou');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001400, /*reading*/'月亮', /*read_type*/1, /*panel_id*/10014, /*detail_text*/'在夜空中散发着金黄色光芒的美丽卫星。', /*version*/1, /*head_symbol*/'üe', /*tail_symbol*/'ang');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001401, /*reading*/'满月', /*read_type*/1, /*panel_id*/10014, /*detail_text*/'指圆形的月亮。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'üe');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001402, /*reading*/'moon', /*read_type*/2, /*panel_id*/10014, /*detail_text*/'“月亮”的英文读音。', /*version*/1, /*head_symbol*/'ei', /*tail_symbol*/'ing');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001403, /*reading*/'luna', /*read_type*/2, /*panel_id*/10014, /*detail_text*/'月亮的拉丁文读音。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'a');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001404, /*reading*/'明月', /*read_type*/2, /*panel_id*/10014, /*detail_text*/'指特别美丽的月亮。', /*version*/1, /*head_symbol*/'ong', /*tail_symbol*/'ie');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001500, /*reading*/'蝙蝠', /*read_type*/1, /*panel_id*/10015, /*detail_text*/'为数不多的飞翔哺乳动物。虽然在人们的心目中，它们会吸血，但真正吸血的只有极少数种类。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'u');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001503, /*reading*/'伊莉亚的眷属', /*read_type*/3, /*panel_id*/10015, /*detail_text*/'只会做一些诸如抚摸小女孩头顶或是抱起小女孩的简单工作。', /*version*/1, /*head_symbol*/'i', /*tail_symbol*/'u');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001600, /*reading*/'鸟', /*read_type*/1, /*panel_id*/10016, /*detail_text*/'鸟类的统称。全身覆有羽毛，利用翅膀来飞翔。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'ei');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001601, /*reading*/'魔物', /*read_type*/1, /*panel_id*/10016, /*detail_text*/'出现在兰德索尔全境的怪物的统称。', /*version*/1, /*head_symbol*/'o', /*tail_symbol*/'u');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001603, /*reading*/'基兹', /*read_type*/2, /*panel_id*/10016, /*detail_text*/'被封印在书中的鸟型魔物。被初音&栞姐妹击退。', /*version*/1, /*head_symbol*/'ü', /*tail_symbol*/'ao');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001604, /*reading*/'怪鸟基兹', /*read_type*/3, /*panel_id*/10016, /*detail_text*/'被封印在书中的鸟型魔物。被初音&栞姐妹击退。', /*version*/1, /*head_symbol*/'ai', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001700, /*reading*/'鞋子', /*read_type*/1, /*panel_id*/10017, /*detail_text*/'穿在脚上的东西。保护脚底不被小石头和口香糖等东西伤害，是文明的进步。', /*version*/1, /*head_symbol*/'ie', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001701, /*reading*/'布鞋', /*read_type*/1, /*panel_id*/10017, /*detail_text*/'“鞋子”的另一种叫法。最近好像都不怎么用这个称呼了吧？', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'üe');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001703, /*reading*/'皮靴', /*read_type*/2, /*panel_id*/10017, /*detail_text*/'从老爷爷到高中女生，使用人群极广的时尚道具。\n可惜的是，就算煮了也不能吃。', /*version*/1, /*head_symbol*/'i', /*tail_symbol*/'ie');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001800, /*reading*/'猫咪', /*read_type*/1, /*panel_id*/10018, /*detail_text*/'猫科哺乳动物。是一种和人类相处多年的动物，在它的可爱面前，人类显得极为无力。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001802, /*reading*/'虎斑猫', /*read_type*/2, /*panel_id*/10018, /*detail_text*/'毛皮图案像虎斑的猫。俗称大花猫。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'ao');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001804, /*reading*/'珠希的朋友们', /*read_type*/3, /*panel_id*/10018, /*detail_text*/'一些猫咪。珠希在养它们，可是开销好像不小。', /*version*/1, /*head_symbol*/'i', /*tail_symbol*/'ou');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001900, /*reading*/'金鱼', /*read_type*/1, /*panel_id*/10019, /*detail_text*/'用于观赏的红色小鱼。在庙会上会忍不住尝试去捞。', /*version*/1, /*head_symbol*/'in', /*tail_symbol*/'ü');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001901, /*reading*/'鱼', /*read_type*/1, /*panel_id*/10019, /*detail_text*/'鱼的常见称呼。据说吃了它就会变得聪明。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'ao');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1001902, /*reading*/'鱼', /*read_type*/1, /*panel_id*/10019, /*detail_text*/'鱼的常见称呼。据说上了年纪以后，比起吃肉，还是更喜欢吃这个。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'ü');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002000, /*reading*/'老鼠', /*read_type*/1, /*panel_id*/10020, /*detail_text*/'一种啮齿动物。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'u');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002001, /*reading*/'mouse', /*read_type*/2, /*panel_id*/10020, /*detail_text*/'“鼠”的英文读音。可爱又受人喜爱的大多会被这样称呼。', /*version*/1, /*head_symbol*/'ie', /*tail_symbol*/'u');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002100, /*reading*/'蛋', /*read_type*/1, /*panel_id*/10021, /*detail_text*/'由雌性鸟类产下，被外壳包裹着的球形物体。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'an');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002101, /*reading*/'egg', /*read_type*/2, /*panel_id*/10021, /*detail_text*/'“蛋”的英文读音。', /*version*/1, /*head_symbol*/'ou', /*tail_symbol*/'ai');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002102, /*reading*/'幼崽', /*read_type*/2, /*panel_id*/10021, /*detail_text*/'幼小的生物。多数都是很小很可爱的。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'u');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002103, /*reading*/'鸟巢', /*read_type*/2, /*panel_id*/10021, /*detail_text*/'鸟类的栖息地，它们会在这里产卵。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'ao');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002200, /*reading*/'船', /*read_type*/1, /*panel_id*/10022, /*detail_text*/'载着人或物在水上行进的交通工具。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'an');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002202, /*reading*/'帆船', /*read_type*/2, /*panel_id*/10022, /*detail_text*/'用风帆航行的船。', /*version*/1, /*head_symbol*/'ang', /*tail_symbol*/'ai');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002300, /*reading*/'牛奶', /*read_type*/1, /*panel_id*/10023, /*detail_text*/'奶牛产出的乳汁。不仅可以直接饮用，还可以加工成奶酪、黄油等奶制品。', /*version*/1, /*head_symbol*/'iu', /*tail_symbol*/'ai');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002301, /*reading*/'milk', /*read_type*/2, /*panel_id*/10023, /*detail_text*/'“牛奶”的英文读音。', /*version*/1, /*head_symbol*/'o', /*tail_symbol*/'ing');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002302, /*reading*/'奶奶', /*read_type*/2, /*panel_id*/10023, /*detail_text*/'“牛奶”的另一种叫法。说出来会让人觉得有点尴尬。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'ai');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002303, /*reading*/'伊丽莎白', /*read_type*/3, /*panel_id*/10023, /*detail_text*/'以伊丽莎白牧场里的奶牛命名，真阳的好搭档。', /*version*/1, /*head_symbol*/'i', /*tail_symbol*/'ai');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002400, /*reading*/'巧克力', /*read_type*/1, /*panel_id*/10024, /*detail_text*/'由可可加工而成的糖果。每到2月14日就会被大量消耗。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002401, /*reading*/'糖果', /*read_type*/1, /*panel_id*/10024, /*detail_text*/'在三餐和宵夜之外的时间食用的零食。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002402, /*reading*/'甜食', /*read_type*/2, /*panel_id*/10024, /*detail_text*/'有甜味的食品。疲劳的时候会想吃。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002403, /*reading*/'可可', /*read_type*/2, /*panel_id*/10024, /*detail_text*/'巧克力的原料。含量越多味道越苦。', /*version*/1, /*head_symbol*/'e', /*tail_symbol*/'ou');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002500, /*reading*/'橡子', /*read_type*/1, /*panel_id*/10025, /*detail_text*/'坚硬的坚果。不太适合人类食用，但是能激发孩子的收集欲，堪称魅惑之树的果实。', /*version*/1, /*head_symbol*/'ang', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002501, /*reading*/'树果', /*read_type*/1, /*panel_id*/10025, /*detail_text*/'能够长成树木的果实。', /*version*/1, /*head_symbol*/'o', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002502, /*reading*/'坚果', /*read_type*/2, /*panel_id*/10025, /*detail_text*/'被硬壳包裹的可食用果实。可以加在点心里，也可以当作下酒菜。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'o');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002503, /*reading*/'铃的小零食', /*read_type*/3, /*panel_id*/10025, /*detail_text*/'虽然比不上豆沙面包，但她似乎也很喜欢。战斗的时候会拿来砸晕敌人。', /*version*/1, /*head_symbol*/'ing', /*tail_symbol*/'in');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002600, /*reading*/'草莓', /*read_type*/1, /*panel_id*/10026, /*detail_text*/'酸甜的小巧水果。看起来像种子的颗粒其实是它的果实。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'ei');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002602, /*reading*/'果酱', /*read_type*/2, /*panel_id*/10026, /*detail_text*/'加工过的水果食品。可以涂在面包、饼干上，或者加进红茶。', /*version*/1, /*head_symbol*/'o', /*tail_symbol*/'ang');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002700, /*reading*/'虎', /*read_type*/1, /*panel_id*/10027, /*detail_text*/'大型猫科猛兽。肉食动物。也可以用来形容醉酒的人。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'u');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002703, /*reading*/'野兽', /*read_type*/2, /*panel_id*/10027, /*detail_text*/'全身覆有毛发，用四足行走的哺乳类动物。', /*version*/1, /*head_symbol*/'e', /*tail_symbol*/'ou');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002704, /*reading*/'茉莉向往的存在', /*read_type*/3, /*panel_id*/10027, /*detail_text*/'猛虎！', /*version*/1, /*head_symbol*/'o', /*tail_symbol*/'ing');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002801, /*reading*/'兔子', /*read_type*/1, /*panel_id*/10028, /*detail_text*/'长耳短尾，可爱的哺乳动物。作为宠物也很受欢迎。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002802, /*reading*/'玩偶', /*read_type*/1, /*panel_id*/10028, /*detail_text*/'模仿人或动物的人工制品。材质也多种多样，有玩具、观赏，祭礼等用途。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'ou');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002804, /*reading*/'亚瑟', /*read_type*/3, /*panel_id*/10028, /*detail_text*/'真步拥有的玩偶里的一只。命名灵感来源于亚瑟王和圆桌骑士。', /*version*/1, /*head_symbol*/'a', /*tail_symbol*/'e');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002900, /*reading*/'炸弹', /*read_type*/1, /*panel_id*/10029, /*detail_text*/'通过爆炸产生的热量和冲击力来摧毁、杀伤目标的武器。超级危险。', /*version*/1, /*head_symbol*/'a', /*tail_symbol*/'an');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002901, /*reading*/'bomb', /*read_type*/2, /*panel_id*/10029, /*detail_text*/'“炸弹”的英文读音。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002902, /*reading*/'危险物品', /*read_type*/2, /*panel_id*/10029, /*detail_text*/'可能对生物或环境造成危害的物质。处理这些物质有时还需要特殊的资格。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'u');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002903, /*reading*/'远程武器', /*read_type*/2, /*panel_id*/10029, /*detail_text*/'指从远处发射进行攻击的武器。有时也被用来比喻异想天开的想法或点子。', /*version*/1, /*head_symbol*/'o', /*tail_symbol*/'ao');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1002904, /*reading*/'未奏希的恶作剧道具', /*read_type*/3, /*panel_id*/10029, /*detail_text*/'还是让她挨顿骂反省反省比较好。', /*version*/1, /*head_symbol*/'ei', /*tail_symbol*/'ü');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003000, /*reading*/'西瓜', /*read_type*/1, /*panel_id*/10030, /*detail_text*/'葫芦科的大型水果。外皮图案为绿色条纹，内含红色的果肉和黑色的种子，这种特征令人印象深刻。', /*version*/1, /*head_symbol*/'i', /*tail_symbol*/'a');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003002, /*reading*/'夏季的风物诗', /*read_type*/2, /*panel_id*/10030, /*detail_text*/'夏季的代表物。除了西瓜，还有大海、烟花等。', /*version*/1, /*head_symbol*/'a', /*tail_symbol*/'ing');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003100, /*reading*/'马', /*read_type*/1, /*panel_id*/10031, /*detail_text*/'马科的大型哺乳动物。因为力气大、跑得快，常用作家畜和赛马。', /*version*/1, /*head_symbol*/'a', /*tail_symbol*/'a');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003101, /*reading*/'驴', /*read_type*/1, /*panel_id*/10031, /*detail_text*/'马科的哺乳动物。与马相比体型更小，但力气很大，被人们视为劳动力。', /*version*/1, /*head_symbol*/'ü', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003102, /*reading*/'horse', /*read_type*/1, /*panel_id*/10031, /*detail_text*/'“马”的英文读音。', /*version*/1, /*head_symbol*/'ün', /*tail_symbol*/'a');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003104, /*reading*/'纯种赛马', /*read_type*/2, /*panel_id*/10031, /*detail_text*/'一种改良过的赛马品种。', /*version*/1, /*head_symbol*/'un', /*tail_symbol*/'a');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003105, /*reading*/'暗黑独角兽', /*read_type*/3, /*panel_id*/10031, /*detail_text*/'在团队战中登场的马型魔物。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'ou');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003200, /*reading*/'椅子', /*read_type*/1, /*panel_id*/10032, /*detail_text*/'可以坐的家具。也能用于彰显职位、地位。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'eng');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003201, /*reading*/'家具', /*read_type*/2, /*panel_id*/10032, /*detail_text*/'放置在室内用于日常使用的工具的统称。', /*version*/1, /*head_symbol*/'a', /*tail_symbol*/'ü');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003203, /*reading*/'公会之家道具', /*read_type*/3, /*panel_id*/10032, /*detail_text*/'放在公会之家里的家具和装饰品。从设计奢华到极具特色的东西都有，种类繁多。', /*version*/1, /*head_symbol*/'ong', /*tail_symbol*/'ü');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003204, /*reading*/'木椅', /*read_type*/3, /*panel_id*/10032, /*detail_text*/'公会之家道具，朴素的木质椅子。简单但很结实。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003300, /*reading*/'大海', /*read_type*/1, /*panel_id*/10033, /*detail_text*/'陆地外的凹处，会积水的地方。', /*version*/1, /*head_symbol*/'a', /*tail_symbol*/'ai');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003301, /*reading*/'海岸', /*read_type*/1, /*panel_id*/10033, /*detail_text*/'陆地与海洋接壤的部分。', /*version*/1, /*head_symbol*/'ai', /*tail_symbol*/'an');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003303, /*reading*/'海潮声', /*read_type*/2, /*panel_id*/10033, /*detail_text*/'海浪拍打陆地发出的声音。把耳朵贴在贝壳上也能听到类似的声音。', /*version*/1, /*head_symbol*/'o', /*tail_symbol*/'eng');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003400, /*reading*/'寄居蟹', /*read_type*/1, /*panel_id*/10034, /*detail_text*/'背着贝壳生活的甲壳类动物。', /*version*/1, /*head_symbol*/'i', /*tail_symbol*/'ie');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003401, /*reading*/'贝壳', /*read_type*/2, /*panel_id*/10034, /*detail_text*/'包裹在软体动物外部的贝壳。看到它们散落在沙滩上，就让人忍不住想捡走。', /*version*/1, /*head_symbol*/'ei', /*tail_symbol*/'e');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003402, /*reading*/'甲壳纲', /*read_type*/2, /*panel_id*/10034, /*detail_text*/'有坚硬外骨骼的节肢动物。虾、螃蟹还有水蚤也属于此类。', /*version*/1, /*head_symbol*/'a', /*tail_symbol*/'ang');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003500, /*reading*/'笛子', /*read_type*/1, /*panel_id*/10035, /*detail_text*/'一般指木管乐器。细分为竖笛和横笛。', /*version*/1, /*head_symbol*/'i', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003501, /*reading*/'竖笛', /*read_type*/1, /*panel_id*/10035, /*detail_text*/'一种木管乐器。不可以拿来当古装剧里的刀剑挥舞。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003502, /*reading*/'管乐器', /*read_type*/2, /*panel_id*/10035, /*detail_text*/'乐器的分类之一。通过吹气使管内的空气振动，就能发出声音。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003600, /*reading*/'书', /*read_type*/1, /*panel_id*/10036, /*detail_text*/'把文字和图片印刷出来，装订在一叠纸上制成的东西。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'en');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003601, /*reading*/'笔记本', /*read_type*/1, /*panel_id*/10036, /*detail_text*/'用来书写文字和图片的文具。', /*version*/1, /*head_symbol*/'i', /*tail_symbol*/'en');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003602, /*reading*/'小说', /*read_type*/2, /*panel_id*/10036, /*detail_text*/'创作出来的故事。有恋爱、历史、推理等多种多样的题材。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'o');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003604, /*reading*/'凯露的魔导书', /*read_type*/3, /*panel_id*/10036, /*detail_text*/'这是书？还是魔杖？', /*version*/1, /*head_symbol*/'ai', /*tail_symbol*/'u');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003700, /*reading*/'鱼', /*read_type*/1, /*panel_id*/10037, /*detail_text*/'鱼的常见称呼。据说吃了它就会变得聪明。', /*version*/1, /*head_symbol*/'ü', /*tail_symbol*/'ü');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003702, /*reading*/'柴鱼', /*read_type*/2, /*panel_id*/10037, /*detail_text*/'一种鱼类。做成刺身会很好吃。鲣鱼干等加工品也很常见。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'ü');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003703, /*reading*/'金枪鱼', /*read_type*/2, /*panel_id*/10037, /*detail_text*/'一种鱼类。块头又大又美味的高级鱼。说起寿司就会想到这个。', /*version*/1, /*head_symbol*/'in', /*tail_symbol*/'ü');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1003800, /*reading*/'树', /*read_type*/1, /*panel_id*/10038, /*detail_text*/'指树木。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'u');
