INSERT INTO `srt_panel` VALUES (/*reading_id*/1003804, /*reading*/'忘却的颂歌', /*read_type*/3, /*panel_id*/10038, /*detail_text*/'与千歌在咲恋救济院里引发的圣夜奇迹物语。', /*version*/1, /*head_symbol*/'ang', /*tail_symbol*/'e');
