INSERT INTO `srt_panel` VALUES (/*reading_id*/1003903, /*reading*/'克罗依的点心', /*read_type*/3, /*panel_id*/10039, /*detail_text*/'仅仅是拿在手上就觉得赏心悦目。', /*version*/1, /*head_symbol*/'e', /*tail_symbol*/'in');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004000, /*reading*/'锤子', /*read_type*/1, /*panel_id*/10040, /*detail_text*/'头部由金属制成的钝器。要是被它打到会很疼。', /*version*/1, /*head_symbol*/'ui', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004001, /*reading*/'玩具锤子', /*read_type*/1, /*panel_id*/10040, /*detail_text*/'头部十分柔软，呈手风琴状的玩具。敲打时会发出滑稽的声音。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'ui');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004002, /*reading*/'钉锤', /*read_type*/2, /*panel_id*/10040, /*detail_text*/'头部由金属制成的钝器。要是被它打到会很疼。', /*version*/1, /*head_symbol*/'ing', /*tail_symbol*/'ui');
