INSERT INTO `srt_panel` VALUES (/*reading_id*/1004100, /*reading*/'星星', /*read_type*/1, /*panel_id*/10041, /*detail_text*/'挂在夜空上闪耀的天体。', /*version*/1, /*head_symbol*/'ing', /*tail_symbol*/'ing');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004101, /*reading*/'五边形', /*read_type*/1, /*panel_id*/10041, /*detail_text*/'有五个顶点和边的多边形。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'ing');
