INSERT INTO `srt_panel` VALUES (/*reading_id*/1004105, /*reading*/'一闪一闪', /*read_type*/2, /*panel_id*/10041, /*detail_text*/'光的其中一种表现形式。', /*version*/1, /*head_symbol*/'ang', /*tail_symbol*/'ing');
