INSERT INTO `srt_panel` VALUES (/*reading_id*/1004107, /*reading*/'流星', /*read_type*/3, /*panel_id*/10041, /*detail_text*/'初音的蝴蝶结上的装饰，亦是其必杀技。', /*version*/1, /*head_symbol*/'iu', /*tail_symbol*/'ing');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004200, /*reading*/'帽子', /*read_type*/1, /*panel_id*/10042, /*detail_text*/'戴在头上的变装道具。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'i');
