INSERT INTO `srt_panel` VALUES (/*reading_id*/1004204, /*reading*/'绅士', /*read_type*/2, /*panel_id*/10042, /*detail_text*/'谨守礼仪的男士，也可以指社会地位高的人。', /*version*/1, /*head_symbol*/'en', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004300, /*reading*/'杯子', /*read_type*/1, /*panel_id*/10043, /*detail_text*/'装饮料的容器。', /*version*/1, /*head_symbol*/'ei', /*tail_symbol*/'i');
