INSERT INTO `srt_panel` VALUES (/*reading_id*/1004302, /*reading*/'马克杯', /*read_type*/2, /*panel_id*/10043, /*detail_text*/'“杯子”的其中一种。', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'ei');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004400, /*reading*/'狗', /*read_type*/1, /*panel_id*/10044, /*detail_text*/'会汪汪叫的动物。', /*version*/1, /*head_symbol*/'ou', /*tail_symbol*/'ou');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004403, /*reading*/'灰狼', /*read_type*/2, /*panel_id*/10044, /*detail_text*/'“狗”的同类。充满狂野的力量。', /*version*/1, /*head_symbol*/'ui', /*tail_symbol*/'ang');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004404, /*reading*/'狗子', /*read_type*/2, /*panel_id*/10044, /*detail_text*/'“狗”的另一种叫法。', /*version*/1, /*head_symbol*/'ang', /*tail_symbol*/'ang');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004405, /*reading*/'哈士奇', /*read_type*/2, /*panel_id*/10044, /*detail_text*/'非常像狼的大型犬种，可以作为宠物饲养，前提是你可以接受他许多让人哭笑不得的行为。', /*version*/1, /*head_symbol*/'a', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004500, /*reading*/'旗子', /*read_type*/1, /*panel_id*/10045, /*detail_text*/'轻轻飘起的布料。', /*version*/1, /*head_symbol*/'i', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004502, /*reading*/'战旗', /*read_type*/2, /*panel_id*/10045, /*detail_text*/'军队在战斗时使用的旗子，用以分辨敌我，也可以当作下达指令的工具。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004503, /*reading*/'竖旗', /*read_type*/2, /*panel_id*/10045, /*detail_text*/'指为未来的某件事铺垫，通常是不好的事情。', /*version*/1, /*head_symbol*/'u', /*tail_symbol*/'i');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004504, /*reading*/'终点', /*read_type*/2, /*panel_id*/10045, /*detail_text*/'赛车比赛中终点的黑白旗，通常代表比赛结束。', /*version*/1, /*head_symbol*/'ong', /*tail_symbol*/'an');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004600, /*reading*/'蛋糕', /*read_type*/1, /*panel_id*/10046, /*detail_text*/'很棒的点心。甜甜的很好吃。', /*version*/1, /*head_symbol*/'an', /*tail_symbol*/'ao');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004602, /*reading*/'礼物', /*read_type*/2, /*panel_id*/10046, /*detail_text*/'用来送人最适合不过。', /*version*/1, /*head_symbol*/'i', /*tail_symbol*/'u');
INSERT INTO `srt_panel` VALUES (/*reading_id*/1004603, /*reading*/'好感度点数', /*read_type*/3, /*panel_id*/10046, /*detail_text*/'情谊的深浅并不只由相处时间的长短来决定。卡路里也是情谊的证明……', /*version*/1, /*head_symbol*/'ao', /*tail_symbol*/'u');
