INSERT INTO `srt_panel` VALUES (/*reading_id*/2002400, /*reading*/'铃', /*read_type*/1, /*panel_id*/20024, /*detail_text*/'被派遣到【伊丽莎白牧场】的护卫。她没有偷懒，只是在享受慢节奏的生活。', /*version*/1, /*head_symbol*/'ing', /*tail_symbol*/'ing');
