INSERT INTO `srt_panel` VALUES (/*reading_id*/2002500, /*reading*/'惠理子', /*read_type*/1, /*panel_id*/20025, /*detail_text*/'【暮光流星群】的成员。她的爱很沉重。真的……非常沉重。', /*version*/1, /*head_symbol*/'ui', /*tail_symbol*/'i');
